import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable } from 'rxjs';
import { HealthData } from '../models/health-data.model';

@Injectable({
  providedIn: 'root'
})
export class HealthService {
  private apiUrl = 'http://localhost:8080/api/health';

  constructor(private http: HttpClient) { }


  uploadImage(file: File): Observable<HealthData> {
    const formData = new FormData();
    formData.append('file', file);

    return this.http.post<HealthData>(`${this.apiUrl}/upload`, formData);
  }

  uploadImageWithManualData(file: File, steps: number, calories: number): Observable<HealthData> {
    const formData = new FormData();
    formData.append('file', file);
    formData.append('steps', steps.toString());
    formData.append('calories', calories.toString());

    return this.http.post<HealthData>(`${this.apiUrl}/upload-manual`, formData);
  }

  // Get health data for current user - no userId needed
  getHealthData(): Observable<HealthData[]> {
    // Backend will extract user from Clienta app token
    return this.http.get<HealthData[]>(`${this.apiUrl}/user/current`);
  }

  ping(): Observable<string> {
    return this.http.get<string>(`${this.apiUrl}/ping`, { responseType: 'text' as 'json' });
  }

  // Test method to generate a token for testing Clienta app integration
  generateTestToken(email: string = 'test@example.com', name: string = 'Test User'): Observable<any> {
    return this.http.get(`${this.apiUrl}/test-token`, {
      params: { email, name }
    });
  }
}
